    device_id*: int32
    stream*: HipStream
    wavefront_size*: int32

proc initAMDOptimizer*(): AMDGPUOptimizer =
  var optimizer: AMDGPUOptimizer

  # Initialize HIP
  checkHipErrors(hipInit(0))

  # Get device properties
  var deviceProps: HipDeviceProp
  checkHipErrors(hipGetDeviceProperties(addr deviceProps, 0))

  optimizer.device_id = 0
  optimizer.wavefront_size = deviceProps.warpSize  # AMD calls it wavefront

