  checkHipErrors(hipStreamCreate(addr optimizer.stream))

  return optimizer

# Optimized force calculation kernel for AMD GPUs
const AMD_FORCE_KERNEL = """
#include <hip/hip_runtime.h>

extern "C" __global__ void amd_optimized_force_kernel(
    float* __restrict__ positions,
    float* __restrict__ forces, 
    float* __restrict__ confidence_scores,
    int num_atoms,
    float sigma,
    float epsilon) {

    // Use LDS (Local Data Share) - AMD's equivalent of shared memory
    __shared__ float lds_positions[64 * 3];  // 64 atoms per workgroup
    __shared__ float lds_confidence[64];

    int global_id = hipBlockIdx_x * hipBlockDim_x + hipThreadIdx_x;
    int local_id = hipThreadIdx_x;
    int group_id = hipBlockIdx_x;

    if (global_id >= num_atoms) return;

    // Coalesced loading into LDS with wavefront-aware patterns
    if (local_id < hipBlockDim_x && group_id * hipBlockDim_x + local_id < num_atoms) {
        int atom_idx = group_id * hipBlockDim_x + local_id;
        lds_positions[local_id * 3] = positions[atom_idx * 3];
        lds_positions[local_id * 3 + 1] = positions[atom_idx * 3 + 1];
        lds_positions[local_id * 3 + 2] = positions[atom_idx * 3 + 2];
        lds_confidence[local_id] = confidence_scores[atom_idx];
    }
    __syncthreads();

    float3 atom_pos = make_float3(
        lds_positions[local_id * 3],
        lds_positions[local_id * 3 + 1], 
        lds_positions[local_id * 3 + 2]
    );
    float confidence_i = lds_confidence[local_id];

    float3 total_force = make_float3(0.0f, 0.0f, 0.0f);

    // Wavefront-optimized inner loop
    for (int j = 0; j < hipBlockDim_x; j++) {
        if (j != local_id && group_id * hipBlockDim_x + j < num_atoms) {
            float3 other_pos = make_float3(
                lds_positions[j * 3],
                lds_positions[j * 3 + 1],
                lds_positions[j * 3 + 2]
            );

            float3 dr = make_float3(
                atom_pos.x - other_pos.x,
                atom_pos.y - other_pos.y,
                atom_pos.z - other_pos.z
            );

            float r2 = dr.x * dr.x + dr.y * dr.y + dr.z * dr.z;

            if (r2 > 0.0f) {
                float r = sqrtf(r2);
                float confidence_j = lds_confidence[j];
                float avg_confidence = (confidence_i + confidence_j) * 0.5f;

                // AMD-optimized LJ calculation using native math functions
                float sr = __fdividef(sigma, r);  // Fast division
                float sr2 = sr * sr;
                float sr6 = sr2 * sr2 * sr2;
                float sr12 = sr6 * sr6;

                float force_magnitude = epsilon * avg_confidence * 24.0f * 
                                      __fdividef(2.0f * sr12 - sr6, r);

                total_force.x += force_magnitude * __fdividef(dr.x, r);
                total_force.y += force_magnitude * __fdividef(dr.y, r);
                total_force.z += force_magnitude * __fdividef(dr.z, r);
            }
        }
    }

    // Inter-group interactions with optimized memory access patterns
    for (int other_group = 0; other_group < hipGridDim_x; other_group++) {
        if (other_group != group_id) {
            for (int j = 0; j < hipBlockDim_x; j++) {
                int other_atom = other_group * hipBlockDim_x + j;
                if (other_atom < num_atoms) {
                    float3 other_pos = make_float3(
                        positions[other_atom * 3],
                        positions[other_atom * 3 + 1],
                        positions[other_atom * 3 + 2]
                    );

                    float3 dr = make_float3(
                        atom_pos.x - other_pos.x,
                        atom_pos.y - other_pos.y,
                        atom_pos.z - other_pos.z
                    );

                    float r2 = dr.x * dr.x + dr.y * dr.y + dr.z * dr.z;

                    if (r2 > 0.0f) {
                        float r = sqrtf(r2);
                        float confidence_j = confidence_scores[other_atom];
                        float avg_confidence = (confidence_i + confidence_j) * 0.5f;

                        float sr = __fdividef(sigma, r);
                        float sr2 = sr * sr;
                        float sr6 = sr2 * sr2 * sr2;
                        float sr12 = sr6 * sr6;

                        float force_magnitude = epsilon * avg_confidence * 24.0f * 
                                              __fdividef(2.0f * sr12 - sr6, r);

                        total_force.x += force_magnitude * __fdividef(dr.x, r);
                        total_force.y += force_magnitude * __fdividef(dr.y, r);
                        total_force.z += force_magnitude * __fdividef(dr.z, r);
                    }
                }
            }
        }
    }

    // Write back with coalesced access
    forces[global_id * 3] = total_force.x;
    forces[global_id * 3 + 1] = total_force.y;
    forces[global_id * 3 + 2] = total_force.z;
}
"""

