-- Complex number operations with proofs
_+c_ : Complex → Complex → Complex
(r₁ +i i₁) +c (r₂ +i i₂) = (r₁ + r₂) +i (i₁ + i₂)

_*c_ : Complex → Complex → Complex
(r₁ +i i₁) *c (r₂ +i i₂) = (r₁ * r₂ - i₁ * i₂) +i (r₁ * i₂ + i₁ * r₂)

-- Magnitude squared
|_|² : Complex → ℝ
| r +i i |² = r * r + i * i

-- Complex conjugate
_* : Complex → Complex
(r +i i) * = r +i (- i)

-- Quantum state as normalized complex vector
QuantumState : ℕ → Set
QuantumState n = Σ (Vec Complex n) (λ ψ → Normalized ψ)

-- Normalization predicate
Normalized : {n : ℕ} → Vec Complex n → Set
Normalized {n} ψ = ∑ᵢ | lookup ψ i |² ≡ 1.0

-- Quantum gates as unitary matrices
record QuantumGate (n : ℕ) : Set where
  constructor mkGate
  field
    matrix : Matrix Complex n n
    unitary : Unitary matrix

