Unitary : {n : ℕ} → Matrix Complex n n → Set
Unitary {n} U = (U †) ∘ₘ U ≡ Iₙ

-- Hermitian conjugate
_† : {n m : ℕ} → Matrix Complex n m → Matrix Complex m n
(M †) i j = (M j i) *

-- Matrix multiplication
_∘ₘ_ : {n m p : ℕ} → Matrix Complex n m → Matrix Complex m p → Matrix Complex n p
(A ∘ₘ B) i k = ∑ⱼ (A i j *c B j k)

-- Identity matrix
Iₙ : (n : ℕ) → Matrix Complex n n
Iₙ n i j with i ≟ j
... | yes _ = 1.0 +i 0.0
... | no  _ = 0.0 +i 0.0

-- Quantum gate application preserves normalization
gate-preserves-normalization : {n : ℕ} (U : QuantumGate n) (ψ : QuantumState n) 
                             → Normalized (apply-gate U ψ)
gate-preserves-normalization {n} U (ψ , norm-ψ) = 
  begin
    ∑ᵢ | lookup (U.matrix ∘ᵥ ψ) i |²
  ≡⟨ matrix-vector-norm-preservation U.matrix ψ ⟩
    ∑ᵢ | lookup ψ i |²
  ≡⟨ norm-ψ ⟩
    1.0
  ∎

-- Quantum Fourier Transform verification
QFT : (n : ℕ) → QuantumGate (2^ n)
QFT n = mkGate (qft-matrix n) (qft-unitary n)

qft-matrix : (n : ℕ) → Matrix Complex (2^ n) (2^ n)
qft-matrix n i j = (1 / √(2^ n)) * ω^ (i * j)
  where
    ω = exp (2 * π * i / (2^ n))

qft-unitary : (n : ℕ) → Unitary (qft-matrix n)
qft-unitary n = 
